package org.lira.receiver;
import org.json.*;import java.nio.file.*;import java.io.*;import java.security.*;import java.util.*;
public class DictationEngineV2Test {
 static class DurableSound extends DictationEngineTest.Sound {
  DictationStateStore store;
  @Override public void play(String t,String h,String a,int r,DictationEngine.Completion done) {
   try {JSONObject saved=store.load();check(saved.getJSONArray("steps").getJSONObject(saved.getInt("index")).getString("kind").equals("dictation"),"confirmed cursor persisted before next audio starts");}catch(Exception failure){throw new AssertionError(failure);}
   super.play(t,h,a,r,done);
  }
 }

 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static JSONObject cmd(DictationEngine e,String action)throws Exception{JSONObject s=e.status(),t=s.getJSONObject("task"),item=s.getJSONArray("steps").getJSONObject(s.getInt("index"));return new JSONObject().put("schema_version",2).put("task_id",t.getString("task_id")).put("content_hash",t.getString("content_hash")).put("run_epoch",s.getInt("run_epoch")).put("command_id",UUID.randomUUID().toString()).put("expected_state_revision",s.getLong("state_revision")).put("phase_id",item.getString("phase_id")).put("item_id",item.getString("item_id")).put("action",action);}
 static JSONObject scope(DictationEngine e)throws Exception{JSONObject s=e.status(),t=s.getJSONObject("task");return new JSONObject().put("task_id",t.getString("task_id")).put("content_hash",t.getString("content_hash")).put("run_epoch",s.getInt("run_epoch"));}
 public static void main(String[] a)throws Exception {
  DictationEngineTest.Time clock=new DictationEngineTest.Time();DurableSound sound=new DurableSound();File dir=Files.createTempDirectory("v2-engine").toFile();
  TaskAssetStore assets=new TaskAssetStore(new File(dir,"assets"));DictationStateStore store=new DictationStateStore(new File(dir,"state"));sound.store=store;final StringBuilder visible=new StringBuilder();DictationEngine.Display display=(k,w,t)->{visible.append(k).append(w).append(t);};
  JSONObject task=new JSONObject(new String(Files.readAllBytes(Paths.get(a[0])),"UTF-8"));JSONArray recognizers=task.getJSONArray("phases").getJSONObject(0).getJSONArray("items");for(String character:new String[]{"明","湖"}){task.getJSONArray("lessons").getJSONObject(0).getJSONArray("two_targets").put(character);recognizers.put(new JSONObject().put("item_id","recognize-"+character.codePointAt(0)).put("lesson_id","lesson-1").put("text",character).put("covers",new JSONArray().put(character)).put("audio_asset_id",JSONObject.NULL));}byte[] pcm={0,0};StringBuilder sha=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(pcm))sha.append(String.format("%02x",b&255));task.getJSONArray("audio_assets").getJSONObject(0).put("sha256",sha.toString());task.put("content_hash",DictationSpec.contentHash(task));String tid=task.getString("task_id"),hash=task.getString("content_hash"),asset="audio-2";assets.begin(tid,hash,asset,2,sha.toString());assets.append(tid,hash,asset,0,pcm);assets.commit(tid,hash,asset);
  JSONObject manifest=new JSONObject().put("task_id",tid).put("content_hash",hash).put("assets",new JSONArray().put(new JSONObject().put("asset_id",asset).put("sha256",sha.toString()).put("pcm_bytes",2).put("frames",1).put("sample_rate",24000).put("channels",1)));
  DictationEngine e=new DictationEngine(clock,sound,display,store,assets);e.start(new JSONObject().put("task",task).put("manifest",manifest).put("run_epoch",3));check(sound.plays==0&&e.status().getString("state").equals("waiting_start"),"explicit start only");
  final boolean[] explanationBusy={false};
  DictationEngine.ExplanationAudio explanation=new DictationEngine.ExplanationAudio(){public boolean busy(){return explanationBusy[0];}public JSONObject request(String path,JSONObject data){if(path.equals("/audio/start"))explanationBusy[0]=true;return new JSONObject();}};
  e.setExplanationAudio(explanation);
  explanationBusy[0]=true;try{e.start(new JSONObject().put("task",task).put("manifest",manifest).put("run_epoch",3));throw new AssertionError("task start accepted while explanation busy");}catch(IllegalStateException expected){}explanationBusy[0]=false;
  try{e.explanationAudio("/audio/start",new JSONObject());throw new AssertionError("unpaused explanation accepted");}catch(IllegalStateException expected){}
  JSONObject start=cmd(e,"start");e.control(start);e.control(start);check(e.status().getString("state").equals("waiting_child"),"recognition waits");try{e.explanationAudio("/audio/start",new JSONObject());throw new AssertionError("waiting child explanation accepted");}catch(IllegalStateException expected){}clock.t=1000;e.tick();check(e.status().getInt("index")==0,"timer never advances recognition");e.displaySize(640,480);int pageEnd=e.status().getInt("page_end");e.control(cmd(e,"confirm"));check(e.status().getInt("index")==pageEnd+1,"page confirms all visible constituents after resize");check(e.status().getInt("index")==2&&sound.plays==0,"small screen uses two large words and waits for next page");e.control(cmd(e,"confirm"));check(e.status().getInt("index")==3,"last recognition page completes before dictation");check(sound.plays==1&&sound.repeats==1,"single drained play");
  try{e.explanationAudio("/audio/start",new JSONObject());throw new AssertionError("playing explanation accepted");}catch(IllegalStateException expected){}
  DictationEngine.Completion late=sound.done;e.control(cmd(e,"pause"));late.done(true);check(e.status().getInt("actual_repeats")==0,"pause fences late drain");e.explanationAudio("/audio/start",new JSONObject());check(store.load().optBoolean("remote_pause_lock"),"explanation lock durable before playback");
  try{e.control(cmd(e,"resume"));throw new AssertionError("resume accepted during explanation");}catch(IllegalStateException expected){}
  e.localControl("resume");check(e.status().getString("state").equals("paused"),"physical remote blocked during explanation");
  e.explanationAudio("/audio/end",new JSONObject());check(explanationBusy[0],"end acceptance is not playback drain");
  e.explanationAudio("/audio/stop",new JSONObject());check(explanationBusy[0],"stop acceptance still awaits transport cleanup");
  try{e.control(cmd(e,"resume"));throw new AssertionError("resume accepted during drain or cancellation cleanup");}catch(IllegalStateException expected){}
  explanationBusy[0]=false; // Only actual transport completion (including drain/cleanup) clears busy.
  int beforeRequest=sound.plays;e.localControl("resume");check(e.status().getString("state").equals("paused")&&sound.plays==beforeRequest,"remote confirm waits device answer drain");JSONArray requestEvents=e.pendingEvents();check(requestEvents.getJSONObject(requestEvents.length()-1).getString("action").equals("resume_requested")&&requestEvents.getJSONObject(requestEvents.length()-1).isNull("command_id"),"trusted native resume request receipt");e.control(cmd(e,"resume"));sound.drain();check(e.status().getInt("actual_repeats")==1,"first actual drain");clock.t+=2999;e.tick();check(sound.plays==2,"repeat waits configured interval");clock.t++;e.tick();check(sound.plays==3,"repeat starts after interval");sound.drain();check(e.status().getString("state").equals("waiting_child"),"drain waits child");
  e.control(cmd(e,"replay"));sound.drain();check(e.status().getString("state").equals("waiting_child")&&e.status().getInt("actual_repeats")==3,"replay adds exactly one drained utterance");e.control(cmd(e,"replay"));sound.done.done(false);check(e.status().getString("state").equals("failed_item")&&e.status().getInt("actual_repeats")==3,"failed audio uncounted");e.control(cmd(e,"replay"));sound.drain();clock.t+=3000;e.tick();sound.drain();check(e.status().getInt("actual_repeats")==5,"cumulative replay count");
  clock.t+=20000;e.tick();check(e.status().getString("state").equals("paused"),"expired lease pauses");e.lease(scope(e).put("lease_ms",10000));check(e.status().getString("state").equals("paused"),"renew no autoresume");
  DictationEngineTest.Sound recoverySound=new DictationEngineTest.Sound();DictationEngine recovered=new DictationEngine(clock,recoverySound,display,store,assets);check(recovered.status().getString("state").equals("paused"),"reboot persists pause");JSONArray events=recovered.events(scope(recovered).put("after",0).put("limit",1000)).getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject event=events.getJSONObject(i);check(event.getInt("sequence")==i+1,"ordered durable events");check(event.get("occurred_at") instanceof String,"timestamp wire string");check(event.getLong("elapsed_ms")>=0,"boot scoped monotonic event time");}check(!visible.toString().contains("晴天"),"answer never displayed");
  try{recovered.ack(scope(recovered).put("through_sequence",events.length()+1));throw new AssertionError("future ack accepted");}catch(IllegalArgumentException ok){}recovered.ack(scope(recovered).put("through_sequence",events.length()));check(recovered.pendingEvents().length()==0,"ack durably removes receipts");
  try{recovered.control(cmd(recovered,"resume"));throw new AssertionError("reboot resumed before fresh lease");}catch(IllegalStateException expected){}recovered.lease(scope(recovered).put("lease_ms",10000));recovered.control(cmd(recovered,"resume"));recoverySound.drain();clock.t+=3000;recovered.tick();recoverySound.drain();recovered.control(cmd(recovered,"confirm"));check(recovered.status().getString("state").equals("completed"),"exactly one final completion");recovered.ack(scope(recovered).put("through_sequence",recovered.status().getLong("sequence")));JSONObject next=new JSONObject(task.toString()).put("task_id","next-v2");next.put("content_hash",DictationSpec.contentHash(next));String nextHash=next.getString("content_hash");assets.begin("next-v2",nextHash,asset,2,sha.toString());assets.append("next-v2",nextHash,asset,0,pcm);assets.commit("next-v2",nextHash,asset);JSONObject nextManifest=new JSONObject(manifest.toString()).put("task_id","next-v2").put("content_hash",nextHash);recovered.start(new JSONObject().put("task",next).put("manifest",nextManifest).put("run_epoch",1));check(recovered.status().getString("state").equals("waiting_start"),"terminal acknowledged task permits new receipt");JSONArray raw=new JSONArray();for(int i=0;i<40;i++)raw.put(new JSONObject().put("text","清"));JSONArray wide=WordPageLayout.pages(raw,1920,900),narrow=WordPageLayout.pages(raw,640,900);check(narrow.length()>wide.length(),"adaptive capacity");int total=0;for(int i=0;i<narrow.length();i++)total+=narrow.getJSONArray(i).length();check(total==40,"all raw Han exactly once");System.out.println("v2 explicit start, drain intervals, replay, failure, pause fence, lease, reboot, durable ACK, safe UI and adaptive pages passed");
 }
}
